const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');function closeMenu(){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Menü öffnen')}menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen');nav.classList.toggle('open',open)});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){closeMenu();menu?.focus()}});const service=new URLSearchParams(location.search).get('leistung');const email=document.getElementById('inquiry-email');if(service&&email){const label=document.getElementById('chosen-service');label.textContent='Ihre Anfrage: '+service;label.hidden=false;email.href='mailto:info@dreieck-berlin.de?subject='+encodeURIComponent('Anfrage: '+service)}